<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\ResultStorageService;use App\Services\SpecialCategoryService;
Auth::requireAdmin();$pdo=Database::connection();SpecialCategoryService::ensureSchema($pdo);$userId=(int)(Auth::user()['id']??0);$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$error='';$notice='';
function ssSuper():bool{try{if(method_exists(Auth::class,'isSuperAdmin')&&Auth::isSuperAdmin())return true;}catch(Throwable){}$u=Auth::user();$r=strtolower(str_replace(['-',' '],'_',trim((string)($u['role']??''))));return in_array($r,['super_admin','superadmin','owner','root','system_admin'],true)||!empty($u['is_super_admin']);}
function ssOrdinal(int $n):string{if($n%100>=11&&$n%100<=13)return$n.'th';return$n.([1=>'st',2=>'nd',3=>'rd'][$n%10]??'th');}
function ssRound(PDO $pdo,int $id):array{$s=$pdo->prepare("SELECT r.*,e.name event_name,e.event_date,e.venue FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id AND r.round_type='final' AND r.dance_style='salsa' AND r.division IN('salsa_rising','salsa_open') LIMIT 1");$s->execute(['id'=>$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('Salsa Rising/Open Final round not found.');return$r;}
function ssPairs(PDO $pdo,array $round):array{$s=$pdo->prepare("SELECT fp.id pair_id,fr.final_rank,le.competitor_id leader_id,le.display_name leader_name,le.bib_number leader_bib,fe.competitor_id follower_id,fe.display_name follower_name,fe.bib_number follower_bib FROM bdc_scoring_final_pairs fp JOIN bdc_scoring_final_results fr ON fr.round_id=fp.round_id AND fr.pair_id=fp.id JOIN bdc_scoring_entries le ON le.id=fp.leader_entry_id JOIN bdc_scoring_entries fe ON fe.id=fp.follower_entry_id WHERE fp.round_id=:r AND fp.pairing_status='confirmed' ORDER BY fr.final_rank,fp.pair_number");$s->execute(['r'=>$round['id']]);$rows=$s->fetchAll();if(!$rows)throw new RuntimeException('Calculate and submit Final rankings before publication.');foreach($rows as &$row){$row['points']=SpecialCategoryService::fixedPoints((string)$round['division'],(int)$row['final_rank']);$row['leader_bucket']=SpecialCategoryService::pointDivision($pdo,(int)$row['leader_id'],'leader','salsa');$row['follower_bucket']=SpecialCategoryService::pointDivision($pdo,(int)$row['follower_id'],'follower','salsa');}unset($row);return$rows;}
function ssPublication(PDO $pdo,int $roundId):?array{$s=$pdo->prepare('SELECT * FROM bdc_scoring_publications WHERE final_round_id=:r LIMIT 1');$s->execute(['r'=>$roundId]);return$s->fetch()?:null;}
function ssAudit(PDO $pdo,int $roundId,int $userId,string $action,array $details=[]):void{$pdo->prepare('INSERT INTO bdc_scoring_audit(round_id,user_id,action,details_json) VALUES(:r,:u,:a,:d)')->execute(['r'=>$roundId,'u'=>$userId?:null,'a'=>$action,'d'=>json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}
function ssSafe(string $s):string{return trim((string)preg_replace('/[^A-Za-z0-9_-]+/','-',trim($s)),'-')?:'result';}
function ssWrite(string $name,string $html):array{$root=ResultStorageService::root();if(!is_dir($root)&&!mkdir($root,0755,true)&&!is_dir($root))throw new RuntimeException('Could not create result storage.');$path=$root.'/'.$name;if(file_put_contents($path,$html)===false)throw new RuntimeException('Could not write result file.');@chmod($path,0644);return['name'=>$name,'path'=>$path,'relative'=>ResultStorageService::relative($name),'url'=>ResultStorageService::publicUrl($name)];}
function ssPage(string $event,string $title,string $body):string{return'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.htmlspecialchars($title,ENT_QUOTES,'UTF-8').'</title><style>body{font-family:Arial,sans-serif;margin:32px;color:#171717}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #d7d7d7;padding:8px}th{background:#171717;color:#fff}</style></head><body><h1>'.htmlspecialchars($event,ENT_QUOTES,'UTF-8').'</h1><h2>'.htmlspecialchars($title,ENT_QUOTES,'UTF-8').'</h2>'.$body.'</body></html>';}
function ssArchives(PDO $pdo,array $round,array $pairs):array{$label=SpecialCategoryService::label((string)$round['division']);$date=(string)($round['event_date']?:date('Y-m-d'));$base=ssSafe((string)$round['event_name']).'-'.ssSafe($label).'-'.$date;$heatsIdStmt=$pdo->prepare("SELECT id FROM bdc_scoring_rounds WHERE event_id=:e AND dance_style='salsa' AND division=:d AND round_type='heats' ORDER BY id ASC LIMIT 1");$heatsIdStmt->execute(['e'=>$round['event_id'],'d'=>$round['division']]);$heatsId=(int)$heatsIdStmt->fetchColumn();$heats='<table><tr><th>Role</th><th>Bib</th><th>Competitor</th><th>Rank</th><th>Status</th></tr>';if($heatsId){$h=$pdo->prepare("SELECT se.dance_role,se.bib_number,se.display_name,sr.rank_number,sr.result_status FROM bdc_scoring_entries se LEFT JOIN bdc_scoring_results sr ON sr.round_id=se.round_id AND sr.entry_id=se.id WHERE se.round_id=:r AND se.entry_status='active' ORDER BY se.dance_role,sr.rank_number,se.bib_number");$h->execute(['r'=>$heatsId]);foreach($h->fetchAll() as $x)$heats.='<tr><td>'.htmlspecialchars(ucfirst((string)$x['dance_role'])).'</td><td>'.htmlspecialchars((string)$x['bib_number']).'</td><td>'.htmlspecialchars((string)$x['display_name']).'</td><td>'.htmlspecialchars((string)($x['rank_number']??'')).'</td><td>'.htmlspecialchars(ucwords(str_replace('_',' ',(string)($x['result_status']??'')))).'</td></tr>';}else{$heats.='<tr><td colspan="5">Direct-to-Final format. No Heats round was used.</td></tr>';}$heats.='</table>';$final='<table><tr><th>Place</th><th>Leader</th><th>Follower</th></tr>';$points='<p>Fixed special-category points: 5, 4, 3, 2, 1. Points are recorded in each dancer’s Salsa progression bucket.</p><table><tr><th>Place</th><th>Leader</th><th>Follower</th><th>Points Each</th><th>Leader Bucket</th><th>Follower Bucket</th></tr>';foreach($pairs as $p){$final.='<tr><td>'.ssOrdinal((int)$p['final_rank']).'</td><td>'.htmlspecialchars((string)$p['leader_name']).'</td><td>'.htmlspecialchars((string)$p['follower_name']).'</td></tr>';$points.='<tr><td>'.ssOrdinal((int)$p['final_rank']).'</td><td>'.htmlspecialchars((string)$p['leader_name']).'</td><td>'.htmlspecialchars((string)$p['follower_name']).'</td><td>'.(float)$p['points'].'</td><td>'.htmlspecialchars(ucfirst((string)$p['leader_bucket'])).'</td><td>'.htmlspecialchars(ucfirst((string)$p['follower_bucket'])).'</td></tr>';}$final.='</table>';$points.='</table>';return['heats'=>ssWrite($base.'-Heats.html',ssPage((string)$round['event_name'],$label.' Heats',$heats)),'finals'=>ssWrite($base.'-Final.html',ssPage((string)$round['event_name'],$label.' Final',$final)),'points'=>ssWrite($base.'-Points.html',ssPage((string)$round['event_name'],$label.' Final Ranking & Points',$points))];}
$isSuper=ssSuper();
try{$round=ssRound($pdo,$roundId);$pairs=ssPairs($pdo,$round);$publication=ssPublication($pdo,$roundId);if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'');if($action==='submit_for_approval'){if($round['status']!=='scores_submitted')throw new RuntimeException('Final scores must be submitted before requesting approval.');$pdo->beginTransaction();if($publication){$pdo->prepare("UPDATE bdc_scoring_publications SET points_tier='1',status='pending_approval',submitted_by=:u,submitted_at=NOW(),rejected_by=NULL,rejected_at=NULL,rejection_reason=NULL,updated_at=NOW() WHERE id=:id")->execute(['u'=>$userId?:null,'id'=>$publication['id']]);$pid=(int)$publication['id'];}else{$pdo->prepare("INSERT INTO bdc_scoring_publications(event_id,final_round_id,division,points_tier,status,submitted_by,submitted_at,published_at) VALUES(:e,:r,:d,'1','pending_approval',:u,NOW(),NULL)")->execute(['e'=>$round['event_id'],'r'=>$roundId,'d'=>$round['division'],'u'=>$userId?:null]);$pid=(int)$pdo->lastInsertId();}$pdo->prepare("UPDATE bdc_scoring_rounds SET status='pending_approval',publication_id=:p,locked_at=NOW(),locked_by=:u WHERE id=:r")->execute(['p'=>$pid,'u'=>$userId?:null,'r'=>$roundId]);ssAudit($pdo,$roundId,$userId,'salsa_special_submitted',['publication_id'=>$pid,'division'=>$round['division'],'fixed_points'=>[5,4,3,2,1]]);$pdo->commit();$notice='Salsa special-category competition submitted for Super Admin approval. No points have been written yet.';}
if($action==='approve_publication'){if(!$isSuper)throw new RuntimeException('Only Super Admin can approve publication.');$publication=ssPublication($pdo,$roundId);if(!$publication||$publication['status']!=='pending_approval')throw new RuntimeException('No pending approval found.');$archives=ssArchives($pdo,$round,$pairs);$pdo->beginTransaction();try{$pt=$pdo->prepare("INSERT INTO bdc_point_transactions(competitor_id,event_id,dance_style,division,dance_role,points,placement,notes,source_type,source_row_hash,created_by) VALUES(:c,:e,'salsa',:division,:role,:points,:place,:notes,'scoring_engine',:hash,:u)");$pr=$pdo->prepare("INSERT INTO bdc_participant_results(event_id,dance_style,competitor_id,division,dance_role,placement,finalist_status,partner_name,points_awarded,source,point_transaction_id) VALUES(:e,'salsa',:c,:category,:role,:place,:status,:partner,:points,'scoring_engine',:tx)");$link=$pdo->prepare("INSERT INTO bdc_scoring_publication_points(publication_id,pair_id,competitor_id,dance_role,final_rank,points_awarded,point_transaction_id,participant_result_id) VALUES(:p,:pair,:c,:role,:rank,:points,:tx,:result)");foreach($pairs as $pair){foreach([['id'=>(int)$pair['leader_id'],'role'=>'leader','partner'=>$pair['follower_name'],'bucket'=>$pair['leader_bucket']],['id'=>(int)$pair['follower_id'],'role'=>'follower','partner'=>$pair['leader_name'],'bucket'=>$pair['follower_bucket']]] as $person){if($person['id']<1)throw new RuntimeException('Every finalist must have a BDC ID.');$rank=(int)$pair['final_rank'];$points=(float)$pair['points'];$place=ssOrdinal($rank);$hash=hash('sha256','salsa-special|'.$publication['id'].'|'.$person['role'].'|'.$person['id']);$pt->execute(['c'=>$person['id'],'e'=>$round['event_id'],'division'=>$person['bucket'],'role'=>$person['role'],'points'=>$points,'place'=>$place,'notes'=>SpecialCategoryService::label((string)$round['division']).' scoring publication #'.$publication['id'],'hash'=>$hash,'u'=>$userId?:null]);$tx=(int)$pdo->lastInsertId();$pr->execute(['e'=>$round['event_id'],'c'=>$person['id'],'category'=>$round['division'],'role'=>$person['role'],'place'=>$place,'status'=>$rank===1?'winner':($points>0?'placed':'finalist'),'partner'=>$person['partner'],'points'=>$points,'tx'=>$tx]);$result=(int)$pdo->lastInsertId();$link->execute(['p'=>$publication['id'],'pair'=>$pair['pair_id'],'c'=>$person['id'],'role'=>$person['role'],'rank'=>$rank,'points'=>$points,'tx'=>$tx,'result'=>$result]);}}$doc=$pdo->prepare("INSERT INTO bdc_result_documents(event_id,title,document_category,file_type,url,storage_path,status,source,created_by) VALUES(:e,:title,:category,'external',:url,:path,'published','scoring_engine',:u)");$docIds=[];foreach(['heats'=>'HEATS','finals'=>'FINAL','points'=>'FINAL RANKING & POINTS'] as $category=>$suffix){$a=$archives[$category];$doc->execute(['e'=>$round['event_id'],'title'=>strtoupper(SpecialCategoryService::label((string)$round['division'])).' '.$suffix.' — '.$round['event_name'],'category'=>$category,'url'=>$a['url'],'path'=>$a['relative'],'u'=>$userId?:null]);$docIds[$category]=(int)$pdo->lastInsertId();}$pdo->prepare("UPDATE bdc_scoring_publications SET status='published',repository_document_id=:doc,report_url=:url,published_by=:u,approved_by=:u,approved_at=NOW(),published_at=NOW(),updated_at=NOW() WHERE id=:p")->execute(['doc'=>$docIds['points'],'url'=>$archives['points']['url'],'u'=>$userId?:null,'p'=>$publication['id']]);$pdo->prepare("UPDATE bdc_events SET status='completed',updated_at=NOW() WHERE id=:e")->execute(['e'=>$round['event_id']]);$pdo->prepare("UPDATE bdc_scoring_rounds SET status='archived',published_document_id=:doc,locked_at=NOW(),locked_by=:u WHERE id=:r")->execute(['doc'=>$docIds['points'],'u'=>$userId?:null,'r'=>$roundId]);ssAudit($pdo,$roundId,$userId,'salsa_special_approved',['publication_id'=>$publication['id'],'division'=>$round['division'],'fixed_points'=>[5,4,3,2,1],'documents'=>$docIds]);$pdo->commit();$notice='Salsa special-category result approved. Fixed points were added to the Salsa progression ledger.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();foreach($archives as $a)if(is_file($a['path']))@unlink($a['path']);throw$e;}}
if($action==='reject_approval'){if(!$isSuper)throw new RuntimeException('Only Super Admin can reject approval.');$reason=trim((string)($_POST['reason']??''));if($reason==='')throw new RuntimeException('Enter a rejection reason.');$publication=ssPublication($pdo,$roundId);if(!$publication||$publication['status']!=='pending_approval')throw new RuntimeException('No pending approval found.');$pdo->beginTransaction();$pdo->prepare("UPDATE bdc_scoring_publications SET status='rejected',rejected_by=:u,rejected_at=NOW(),rejection_reason=:reason,updated_at=NOW() WHERE id=:p")->execute(['u'=>$userId?:null,'reason'=>$reason,'p'=>$publication['id']]);$pdo->prepare("UPDATE bdc_scoring_rounds SET status='scores_submitted',locked_at=NULL,locked_by=NULL WHERE id=:r")->execute(['r'=>$roundId]);ssAudit($pdo,$roundId,$userId,'salsa_special_rejected',['reason'=>$reason]);$pdo->commit();$notice='Approval rejected. The scorer can amend and resubmit.';}}$round=ssRound($pdo,$roundId);$pairs=ssPairs($pdo,$round);$publication=ssPublication($pdo,$roundId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();$round=$round??null;$pairs=$pairs??[];$publication=$publication??null;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Salsa Special Publication</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">BDC Scoring</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4" style="max-width:1000px"><?php if($round):?><h1 class="h3"><?=e($round['event_name'])?></h1><p class="text-muted"><?=e(SpecialCategoryService::label((string)$round['division']))?> · Fixed 5 / 4 / 3 / 2 / 1 points</p><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($pairs):?><div class="card mb-4"><div class="card-body"><h2 class="h5">Final Ranking & Salsa Progression Points</h2><div class="table-responsive"><table class="table"><thead><tr><th>Place</th><th>Leader</th><th>Follower</th><th>Points Each</th></tr></thead><tbody><?php foreach($pairs as $p):?><tr><td><?=e(ssOrdinal((int)$p['final_rank']))?></td><td><?=e($p['leader_name'])?> <small class="text-muted">→ <?=e(ucfirst($p['leader_bucket']))?></small></td><td><?=e($p['follower_name'])?> <small class="text-muted">→ <?=e(ucfirst($p['follower_bucket']))?></small></td><td><?=e((string)(float)$p['points'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php endif;?><?php $status=(string)($publication['status']??'');if($round&&$round['status']==='scores_submitted'&&$status!=='published'):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><button class="btn btn-primary" name="action" value="submit_for_approval">Submit for Super Admin Approval</button></form><?php elseif($status==='pending_approval'&&$isSuper):?><div class="d-flex gap-3 flex-wrap"><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><button class="btn btn-success" name="action" value="approve_publication">Approve & Publish</button></form><form method="post" class="d-flex gap-2"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input class="form-control" name="reason" placeholder="Rejection reason" required><button class="btn btn-outline-danger" name="action" value="reject_approval">Reject</button></form></div><?php elseif($status==='pending_approval'):?><div class="alert alert-warning">Pending Super Admin approval.</div><?php elseif($status==='published'):?><div class="alert alert-success">Published.</div><?php endif;?></main></body></html>